import{_ as a,o as e,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"前置与启动","description":"","frontmatter":{"title":"前置与启动"},"headers":[],"relativePath":"ts-ai/foundations/getting-started/index.md","filePath":"ts-ai/foundations/getting-started/index.md","lastUpdated":1786083160000}'),n={name:"ts-ai/foundations/getting-started/index.md"};function d(r,t,o,p,l,h){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="前置与启动" tabindex="-1">前置与启动 <a class="header-anchor" href="#前置与启动" aria-label="Permalink to &quot;前置与启动&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本组只补齐运行第一条 LangChain.js 模型调用所需的能力。它不会重复完整的 JavaScript、TypeScript 或 Node.js 课程，也不会要求读者先理解 Agent 循环和后端框架。</p><h2 id="文章与职责" tabindex="-1">文章与职责 <a class="header-anchor" href="#文章与职责" aria-label="Permalink to &quot;文章与职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>主要内容</th><th>建议产物</th></tr></thead><tbody><tr><td><a href="/ts-ai/foundations/getting-started/agent-prerequisites-map">Agent 开发前置知识地图</a></td><td>判断已有的 TS/Node 能力是否足够，并链接到需要补学的前端手册章节</td><td>一份按缺口裁剪的补学清单</td></tr><tr><td><a href="/ts-ai/foundations/getting-started/create-typescript-ai-project">创建 TypeScript AI 项目</a></td><td>Node.js 22 手册基线、ESM、依赖、脚本、TypeScript 与测试配置</td><td>可运行的 <code>ts-ai-starter</code> 项目</td></tr><tr><td><a href="/ts-ai/foundations/getting-started/zod-minimum-introduction">Zod 最小入门</a></td><td>Zod 4 Schema、解析、类型推导、错误与业务约束</td><td>可复用的环境变量校验模块</td></tr></tbody></table><h2 id="学习边界" tabindex="-1">学习边界 <a class="header-anchor" href="#学习边界" aria-label="Permalink to &quot;学习边界&quot;">​</a></h2><p>开始下一组之前，只需做到：</p><ul><li>能阅读 <code>async</code> / <code>await</code>、泛型、联合类型和类型收窄；</li><li>知道 TypeScript 类型在运行时会被擦除，网络和模型输出必须从 <code>unknown</code> 开始校验；</li><li>能使用 ESM <code>import</code> / <code>export</code>、npm 脚本和 <code>process.env</code>；</li><li>能区分“Promise 被拒绝”和“函数返回了不符合业务规则的数据”；</li><li>能运行 TypeScript 类型检查与 Vitest。</li></ul><p>装饰器、NestJS 依赖注入、数据库、队列、向量库和前端状态管理都不是本组前置条件。</p><p>这里采用 Node.js 22 是整本手册的统一工程选择，不是声称当前 LangChain.js 的最低版本就是 22。安装时仍应以 lockfile 中全部依赖的 <code>engines.node</code> 约束为准；本模块的依赖核验快照见<a href="/ts-ai/foundations/">基础与模型总览</a>。</p><h2 id="验收命令" tabindex="-1">验收命令 <a class="header-anchor" href="#验收命令" aria-label="Permalink to &quot;验收命令&quot;">​</a></h2><p>后续文章都沿用同一个示例项目。完成本组后，在项目目录执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>三个命令应分别打印启动信息、完成无错误类型检查、运行测试。真实模型调用要到<a href="/ts-ai/foundations/langchain-bridge/first-chatopenai-invoke">第一次 <code>ChatOpenAI.invoke()</code></a>再加入。</p>`,14)])])}const k=a(n,[["render",d]]);export{u as __pageData,k as default};
